import{S as n,o as t,c as h,a9 as p,B as e}from"./chunks/framework.DxG24V0C.js";const l="/agentsrc/images/opencode/article-05-hero.png",k="/agentsrc/images/opencode/article-05-tasktool.png",r="/agentsrc/images/opencode/article-05-isolation.png",y=JSON.parse('{"title":"OpenCode Agent 系统：SubAgent 与 Claude Code 对比","description":"","frontmatter":{"title":"OpenCode Agent 系统：SubAgent 与 Claude Code 对比"},"headers":[],"relativePath":"opencode/05-agents.md","filePath":"opencode/05-agents.md","lastUpdated":1787409644000}'),d={name:"opencode/05-agents.md"},c=Object.assign(d,{setup(E){const i=[{question:"OpenCode 的 AgentV2 类型系统有三种 Mode（subagent/primary/all），而 Claude Code 的 Agent 是隐式区分。这个 schema 化的 Agent 定义带来了什么核心优势？",options:["在 Agent 运行时显著提升多模态消息的并行处理吞吐效率","以 TypeScript 泛型实现 Agent 类型编程扩展与编译期验证","通过精简 Agent Mode 枚举值降低框架代码的整体维护成本","原生支持跨进程的 Agent Fork 与分布式调度协调能力"],correct:1,explanation:"OpenCode 用 Schema 定义 Agent 类型（branded ID、Mode 枚举、permission 规则集），让 Agent 配置可编程、可验证、可扩展。CC 的 Agent 是隐式区分（通过 querySource 标记），没有公开的类型系统。OpenCode 的优势在于类型安全和工程保障。"},{question:"handleSubtask 中权限检查用的是 Permission.merge(taskAgent.permission, session.permission)。这个双重合并的设计意图是什么？",options:["子 agent 的 Permission 取代父 Session 规则以简化判断","父 Session 的 Deny 规则作为兜底覆盖子 Agent 的宽松权限","子 Agent 与父 Session 的规则各自独立评估后取并集放行","子 Agent 的规则优先但父 Session 冲突时以协商结果为准"],correct:1,explanation:"子 agent 执行时，权限规则集是子 agent permission + 父 session permission 的合并。这意味着父 session 拒绝的操作，子 agent 也无法执行。即使子 agent 的 permission 写得宽松，父 session 的限制仍然有效。"},{question:"OpenCode 用 tasks.pop() 串行调度 SubAgent，Claude Code 用 coordinator 并行模式。OpenCode 选择串行的核心取舍是什么？",options:["串行模型隐藏延迟实际吞吐高于并行模式","串行实现简单适合线性任务流但牺牲了并行响应速度","Effect 系统强制所有 Fiber 以串行方式执行","并行模型无法保证 SubAgent 权限隔离故放弃并行"],correct:1,explanation:"OpenCode 的串行模型简单可控，适合「线性任务流」（探索代码→写代码→review）。代价是放弃并行能力，响应时间比 CC 慢。CC 的 coordinator 并行模式在大规模任务调度上更强大，但实现复杂。这是「实现简单 vs 性能强大」的取舍。"},{question:"OpenCode 默认禁止子 agent 再调 task（嵌套 task）。Claude Code 的 Fork 模式也禁止递归 fork。为什么两个框架都做了这个设计？",options:["递归嵌套 Agent 会引入不可预测的 Token 消耗超出预算控制范围","递归 SubAgent 使状态管理与错误恢复指数级复杂化故直接禁掉","OpenCode 架构上递归调用与 Effect 的 Resource 管理存在冲突","父 Agent 与子 Agent 共享同个模型上下文导致嵌套时上下文污染"],correct:1,explanation:"两个框架都意识到「递归 subagent」会让状态管理指数级变复杂（错误恢复、死循环检测、资源管理），这是个趋同演化——各自独立做了相同的设计决策。"},{question:"explore agent 的 permission 设置是「*: deny」然后显式白名单 grep/glob/list/bash/webfetch/websearch/read。plan agent 用通配符控制 edit 权限（*: deny 但 .opencode/plans/*.md: allow）。这两种模式区别在哪？",options:["属于配置文件书写方式上的表达差异","Explore 全局 Deny 加白名单 Plan 加路径级 Allow","Explore 白名单基于工具类型 Plan 基于目标路径","Plan 通配符比显式白名单扩展性更高"],correct:1,explanation:"explore 的全 deny+白名单适合严格只读角色，不允许任何意外操作。plan 的 deny+路径通配符 allow 实现了更精细的权限——禁止编辑任何文件，但允许写 plan 目录下的计划文件。两种模式针对不同场景，体现了 Permission 通配符系统的灵活性。"}];return(g,s)=>{const a=n("Quiz");return t(),h("div",null,[s[0]||(s[0]=p("",180)),e(a,{questions:i})])}}});export{y as __pageData,c as default};
